\begin{theorem}\label{thm: independent_rate}
Under \cref{ass: Alex2022}, \cref{ass: independent_DCT}, \cref{ass: independent_step}, and \cref{ass: independent_rate}, for any $\delta>0$, we have with probability at least $1-\delta,$ for any $T>0$, the following bound on the expected gradient of the final output under the true parameter $\theta^c$  
\begin{enumerate}
    \item[(i)] If the step size satisfies $a_t=\frac{a}{\sqrt{T}}$, $\forall t \leq T$, for some constant $a<\frac{\sqrt{T}}{L_h}$, then 
    {\small
    \begin{align*}
        & \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2] \\
	    &\leq \left[\frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a\sqrt{T}}\right] + \left[\frac{A_1}{T} + \frac{A_2 \log T}{T} + \frac{A_3 \log^2 T}{T}\right] + \frac{L_h a\sigma^2}{\sqrt{T}},
    \end{align*}
    }
    where $A_1=\frac{C_1 (\log D - \log \delta)}{L_h D}$, $A_2=\frac{C_1 (\log D - \log \delta)}{L_h D} + \frac{C_1}{L_h D}$, $A_3=\frac{C_1}{L_h D}$.
    \item[(ii)]  If the step size satisfies $a_t = \frac{a}{t}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_h}$, then
    {\small
    \begin{align*}
	& \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
	&\leq \left[\frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a} +\frac{6C_1 + \pi^2C_1 (\log D - \log \delta)}{6D}+\frac{\pi^2 L_h a \sigma^2}{6}\right]\frac{1}{\log T}.
    \end{align*}
    }
    \item[(iii)]  If the step size satisfies $a_t = \frac{a}{\sqrt{t}}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_h}$, then
    {\small
    \begin{align*}
	& \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
	&\leq [\frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a\sqrt{T}} + \frac{3C_1(\log D - \log \delta) + 4C_1}{D\sqrt{T}} + \frac{L_h a \sigma^2}{\sqrt{T}}] + \frac{L_h a \sigma^2 \log T}{\sqrt{T}}.
    \end{align*}
    }
\end{enumerate}
\end{theorem}

