	    &\leq \left[\frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a\sqrt{T}}\right] + \left[\frac{A_1}{T} + \frac{A_2 \log T}{T} + \frac{A_3 \log^2 T}{T}\right] + \frac{L_h a\sigma^2}{\sqrt{T}},
    \end{align*}
    }
    where $A_1=\frac{C_1 (\log D - \log \delta)}{L_h D}$, $A_2=\frac{C_1 (\log D - \log \delta)}{L_h D} + \frac{C_1}{L_h D}$, $A_3=\frac{C_1}{L_h D}$.
    \item[(ii)]  If the step size satisfies $a_t = \frac{a}{t}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_h}$, then
    {\small
