    & =  x_{t} - a_{t}	\nabla_x H(x_{t},\theta^c) -  a_{t} B_{t} - a_{t} N_{t},
\end{align*}
where $B_{t}$ is the bias and $N_{t}$ is the noise. By \cref{lemma: independent_concentration}, we know $\mathbb{E}[\|B_{t}\|_2^2]\leq  C_1 \frac{\log Dt + \log \frac{1}{\delta}}{Dt}.$ From \cref{ass: independent_rate} we have $\mathbb{E}[\|N_{t}\|_2^2]\leq \sigma^2.$ By the proof of Lemma 2 in \cite{ajalloeian2020analysis}, we know that 
\begin{align*}
    \mathbb{E}[H(x_{t+1},\theta^c)] - H(x_{t},\theta^c)\leq -\frac{a_{t}}{2}\|\nabla_x H(x_{t},\theta^c) \|_2^2 +\frac{a_{t}}{2}C_1 \frac{\log Dt + \log \frac{1}{\delta}}{Dt} +\frac{a_{t}^2}{2}L_{h} \sigma^2,
\end{align*} 
Rearranging the terms in the inequality above, summing over $t$ from 1 to $T$, and noting that $H(x_{t}, \theta^c) \leq \min_{x \in \mathcal{X}} H(x, \theta^c), \forall t$, we have 
{\small
\begin{align*}
    \sum_{t=1}^{T} a_t \mathbb{E}[\|\nabla_x H(x_{t},\theta^c) \|_2^2]\leq 2
    (H(x_1,\theta^c) - \min_{x \in \mathcal{X}} H(x,\theta^c))
    + C_1 \sum_{t=1}^{T} a_t \frac{\log Dt + \log \frac{1}{\delta}}{Dt} + L_{h}\sigma^2 \sum_{t=1}^{T} a_t^2,
\end{align*}
}
Dividing both sides of the above inequality by $\sum_{t=1}^{T} a_t$, and noting that 
\begin{align*}
    \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2] = \frac{1}{\sum_{t=1}^{T} a_t} \sum_{t=1}^{T} a_t \mathbb{E}[\|\nabla_x H(x_{t},\theta^c) \|_2^2],
\end{align*}
we have
{\small
\begin{align*}
    \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2] \leq \frac{1}{\sum_{t=1}^{T} a_t}\left[2 (H(x_1,\theta^c) - \min_{x \in \mathcal{X}} H(x,\theta^c)) +C_1 \sum_{t=1}^{T} a_t \frac{\log Dt + \log \frac{1}{\delta}}{Dt} + L_{h} \sigma^2\sum_{t=1}^{T}a_t^2.
    \right]
\end{align*}
}
(i) $a_t=\frac{a}{\sqrt{T}}$, $\forall t \leq T$, for some constant $a<\frac{\sqrt{T}}{L_{h}}$. Note that $\sum_{t=1}^{T} \frac{1}{t} \leq \log T+1$ and $\sum_{t=1}^{T} \frac{\log t}{t} \leq \log (\log T+1)$.
Then
{\small
\begin{align*}
    & \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
    &\leq \frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a\sqrt{T}} + \frac{C_1 (\log D - \log \delta) (\log T + 1)}{L_{h} D T} + \frac{C_1 \log T (\log T + 1)}{L_{h} D T} \\ 
    & = \frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a\sqrt{T}} + \frac{C_1 (\log D - \log \delta)}{L_{h} D T} + \frac{C_1 (\log D - \log \delta) \log T}{L_{h} D T} + \frac{C_1 \log^2 T}{L_{h} D T} + \frac{L_{h} a\sigma^2}{\sqrt{T}}
\end{align*}
}
(ii) $a_t = \frac{a}{t}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_{h}}$. Let $M_T=\sum_{t=1}^{T}\frac{1}{t}$. Note that 
\begin{align*}
    \sum_{t=1}^{T}\frac{\log t}{t^2} < \sum_{t=1}^{\infty}\frac{\log t}{t^2} = \frac{\pi^2}{6}(12 \ln A - \gamma - \ln 2\pi) < 1,
\end{align*}
where $A \approx 1.28$ is the Glaisher-Kinkelin constant and $\gamma \approx 0.58$ is the Euler-Mascheroni constant. Then we have
\begin{align*}
	& \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
	&\leq \frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a M_T} +\frac{C_1}{M_T}\sum_{t=1}^T \frac{\log Dt + \log \frac{1}{\delta}}{Dt^2} +\sum_{t=1}^T \frac{L_{h} a \sigma^2}{M_T t^2}\\
	& \leq \left[\frac{2(H(x_1,\theta^c)- \min_{x\in\mathcal{X}}H(x,\theta^c))}{a} +\frac{6C_1 + \pi^2C_1 (\log D - \log \delta)}{6D}+\frac{\pi^2 L_{h} a \sigma^2}{6}\right]\frac{1}{\log T}.
\end{align*}
(iii) $a_t = \frac{a}{\sqrt{t}}$, $\forall t \leq T$, for some constant $a < \frac{1}{L_{h}}$. Let $Q_t=\sum_{t=1}^{T}\frac{1}{\sqrt{t}}$. Note that $\sum_{t=1}^{\infty}\frac{1}{t\sqrt{t}}=\zeta(1.5)\approx2.61<3$, $\sum_{t=1}^{\infty} \frac{\log t}{t\sqrt{t}} < 4$, $\sum_{t=1}^{T}\frac{1}{\sqrt{t}} \geq \sqrt{T}$, where $\zeta(\cdot)$ is the Riemann’s zeta function. Then we have
{\small
\begin{align*}
	& \mathbb{E}[\|\nabla_x H(z_T,\theta^c) \|_2^2]\\
	&\leq \frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a Q_T} +\frac{C_1(\log D - \log \delta)}{D Q_T}\sum_{t=1}^T \frac{1}{t\sqrt{t}} + \frac{C_1}{D Q_T}\sum_{t=1}^{T}\frac{\log t}{t \sqrt{t}} +  \frac{L_{h} a \sigma^2}{Q_T} \sum_{t=1}^T \frac{1}{t}\\
	&\leq \left[\frac{2(H(x_1,\theta^c)- \min_{x}H(x,\theta^c))}{a\sqrt{T}} + \frac{3C_1(\log D - \log \delta) + 4C_1}{D\sqrt{T}} + \frac{L_{h} a \sigma^2}{\sqrt{T}}\right] + \frac{L_{h} a \sigma^2 \log T}{\sqrt{T}}.
\end{align*}
}
\end{proof}

