\begin{lemma}\label{lemma: independent_unbiasedness}
Under \cref{ass: independent_DCT}, $\nabla_{x} h(x, \xi)$ with $\xi \sim f(\cdot;\theta)$ and $\theta \sim \pi_t$ is an unbiased gradient estimator of the objective function in \cref{eq: independent}.
\end{lemma}

\begin{proof}
For every fixed $x\in\mathcal{X}$, 
\begin{align*}
    \mathbb{E}_{\pi_{t}}\left[\mathbb{E}_{f(\cdot;\theta)} [\nabla_x h(x, \xi)]\right] & = \mathbb{E}_{\pi_{t}}\left[\nabla_{x} \mathbb{E}_{f(\cdot;\theta)} [h(x, \xi)]\right]\\
    & = \nabla_{x} \mathbb{E}_{\pi_{t}}\left[\mathbb{E}_{f(\cdot;\theta)} [h(x, \xi)]\right],
\end{align*}
where the first equality holds because the gradient $\nabla_x h(x,\xi)$ is Lipschitz continuous, and the interchange between expectation and differentiation is justified by dominated convergence theorem (DCT). Similarly, the second equality above is again justified by DCT. Therefore, the proposed estimator in \cref{eq: SGD_independent_2} is unbiased gradient estimator of the objective function in \cref{eq: independent}.
\end{proof}

\begin{proof}
For every fixed $x\in\mathcal{X}$, 
\begin{align*}
    \mathbb{E}_{\pi_{t}}\left[\mathbb{E}_{f(\cdot;\theta)} [\nabla_x h(x, \xi)]\right] & = \mathbb{E}_{\pi_{t}}\left[\nabla_{x} \mathbb{E}_{f(\cdot;\theta)} [h(x, \xi)]\right]\\
    & = \nabla_{x} \mathbb{E}_{\pi_{t}}\left[\mathbb{E}_{f(\cdot;\theta)} [h(x, \xi)]\right],
\end{align*}

\begin{align}\label{eq: obj-independent}
    \min _{x \in \mathcal{X}} H(x):=\mathbb{E}_{f(\cdot;\theta^c)}[h(x, \xi)] ~~~\text{(decision-independent uncertainty)}
\end{align}

We now discuss the details of these two steps in the following. Let's first focus on the decision-independent case. Suppose at each time stage $t$ we observe a batch of data $\mathbf{y}_t = \{y_{t,j}, j=1,\ldots,D\}$, where $\{y_{t,j}\}$ are i.i.d. according to $f(\cdot;\theta^c)$ and $D$ is the batch size. By viewing the unknown distributional parameter as a random vector $\theta$ and assuming a prior distribution $\pi_0$ on $\theta$, the posterior distribution of $\theta$ is updated by the Bayes rule as follows:
\begin{align}\label{eq:independent-posterior}
    \pi_t(\theta) = \frac{\pi_{t-1}(\theta)f(\mathbf{y}_t;\theta)}{\int\pi_{t-1}(\theta)f(\mathbf{y}_t;\theta)d\theta} =  \frac{\pi_{t-1}(\theta) \prod_{j=1}^{D} f(y_{t,j};\theta)}{\int\pi_{t-1}(\theta) \prod_{j=1}^{D} f(y_{t,j};\theta)d\theta}.
\end{align}

To estimate the true objective function \eqref{eq: obj-independent}, we consider the Bayesian average of the objective function:
\begin{align}
    \min_{x \in \mathcal{X}} \mathbb{E}_{\pi_{t}}\left[H(x, \theta)\right],
\label{eq: independent}
\end{align}

\begin{algorithm}
\caption{Bayesian-SGD (decision-independent uncertainty)}
\label{algorithm: independent}
\begin{algorithmic}
\STATE{\textbf{input}: data batch size $D$, number of SGD iterations $K$, step size sequence $\{a_{t,j}, t=1,2,\ldots; j=0,\ldots,K-1\}$, time horizon $T$.}
\STATE{\textbf{initialization}: choose an initial decision $x_1$ and prior distribution $\pi_0(\theta)$.}
\FOR{$t =1: T$}
    \STATE{-A batch of data $y_{t,1},\cdots,y_{t,D} \iid f(\cdot; \theta^c)$ arrives;}
    \STATE{-Posterior Update: compute $\pi_t(\theta)$ according to \eqref{eq:independent-posterior}. }
    \STATE{-Decision Update:
        \begin{itemize}
            \item set $x_{t,0}:=x_{t}$;
            \item for $j=0,\cdots,K-1$, draw sample $\theta_{t,j} \sim \pi_t(\theta)$ and $\xi_{t,j} \sim f(\cdot;\theta_{t,j})$, and carry out SGD iteration:
        \end{itemize}
        \begin{align}\label{eq: SGD_independent}
            x_{t,j+1}:=\operatorname{Proj}_{\mathcal{X}}\left\{x_{t,j}-a_{t,j}\nabla_x h(x_{t,j},\xi_{t,j})\right\},
        \end{align}
        ~~~~~~~~~~~~~~where $\operatorname{Proj}_{\mathcal{X}}$ is a projection operator that projects the iterate  to the  set $\mathcal{X}$. 
        \begin{itemize}
            \item set the updated decision as $x_{t+1}:=x_{t,K}$;
        \end{itemize}
    }
\ENDFOR
\RETURN $x_{T+1}$
\end{algorithmic}
\end{algorithm}

\begin{assumption}[\cite{shapiro2021bayesian}, Assumption 3.1] (i) The set $\Theta$ is convex and compact with non-empty interior. (ii) $\ln \pi_0(\theta)$ is bounded on $\Theta$. (iii) $f(\xi|\theta) > 0$ for all $\xi \in \Xi$ and $\theta \in \Theta$. (iv) $f(\xi|\theta)$ is continuous in $\theta \in \Theta$. (v) $\ln f(\xi|\theta), \theta \in \Theta$ is dominated by an integrable (w.r.t. $\xi \sim f(\cdot;\theta^c)$) function. (vi) The data batches are i.i.d. over time from the fixed distribution $f(\cdot;\theta^c)$. 
\label{ass: Alex2022}
\end{assumption}

We then study the asymptotic behavior of \cref{algorithm: independent} by the ordinary differential equation (ODE) method (please refer to \cite{Kushner2003} for a detailed exposition on the ODE method for stochastic approximation). The main idea is that SGD can be viewed as a noisy discretization of an ODE. Under certain conditions, the noise in SGD averages out asymptotically, such that the SGD iterates converge to the solution trajectory of the ODE. For simplicity, we consider the case where $K=1$ and rewrite the SGD iteration \cref{eq: SGD_independent} as
\begin{equation}\label{eq: SGD_independent_2}
    x_{t+1}=x_{t}-a_{t} \nabla_{x} h\left(x_{t}, \xi_{t}\right) + a_t z_t,
\end{equation}

\begin{assumption}\label{ass: independent_DCT}
$h(x,\xi)$ is $C^{1}$-smooth in $x$ for all $\xi \in \Xi$, and the map $\xi \to \nabla_x h(x,\xi)$ is $L_h$-Lipschitz continuous for any $x \in \mathcal{X}$. 
\end{assumption}

\begin{assumption}\label{ass: independent_step}
~
\begin{itemize}
    \item The step size $\{a_t\}$ satisfies $\sum_{t=1}^{\infty} a_{t}^{2}<\infty$, $\sum_{t=1}^{\infty} a_{t}=\infty$, $\lim_{t \to \infty} a_{t} = 0$, $a_t > 0, \forall t > 0$.
    \item The decision space $\mathcal{X} \subset \mathbb{R}^{d}$ is compact and convex.
\end{itemize}
\end{assumption}

\begin{assumption}\label{ass: independent_rate}
~
\begin{itemize}
    \item The parameter space $\Theta$ is finite, i.e., $\Theta = \{\theta_1,\ldots,\theta_k\}$. Moreover, $\theta^c \in \Theta$.
    \item There exists $0<L_{H}<\infty$ such that $||\nabla_x H(x,\theta_1)-\nabla_x H(x,\theta_2)||_2 \leq L_{H}||\theta_1-\theta_2||_2$ for all $\theta_1,\theta_2 \in \Theta$ and for all $x \in \mathcal{X}$.
    \item Sampling variance is bounded by $\sigma^2$, i.e., $\mathbb{E}[||\nabla_x h(x,\xi) - \nabla_x H(x,\theta)||_2^2|\theta] \leq \sigma^2$, for all $\theta \in \Theta$.
\end{itemize}
\end{assumption}
